def parser(log: str) -> dict[str, str]:
    import json
    import re

    results: dict[str, str] = {}
    status_rank = {"pass": 1, "skip": 2, "fail": 3}

    def update(name: str, status: str) -> None:
        if not name or status not in status_rank:
            return
        prev = results.get(name)
        if prev is None or status_rank[status] >= status_rank[prev]:
            results[name] = status

    ansi_re = re.compile(r"\x1b\[[0-9;]*m")
    go_status_re = re.compile(r"^\s*---\s*(PASS|FAIL|SKIP):\s*([^\s(]+)")
    pytest_re = re.compile(r"^(?P<name>\S+::\S+)\s+(?P<status>PASSED|FAILED|SKIPPED|ERROR)\b")
    unittest_re = re.compile(
        r"^(?P<name>test\w+\s*\([^)]+\))\s+\.\.\.\s+(?P<status>ok|FAIL|ERROR|SKIP|skipped)$",
        re.I,
    )

    current_pkg = None

    for line in log.splitlines():
        raw = line.rstrip("\n")
        if not raw.strip():
            continue

        parsed = None
        if raw.lstrip().startswith("{") and raw.rstrip().endswith("}"):
            try:
                parsed = json.loads(raw)
            except json.JSONDecodeError:
                parsed = None

        if parsed:
            pkg = parsed.get("Package") or current_pkg
            if parsed.get("Package"):
                current_pkg = parsed.get("Package")
            action = parsed.get("Action")
            test = parsed.get("Test")

            if action in ("pass", "fail", "skip") and test:
                name = f"{pkg}/{test}" if pkg else test
                status = "pass" if action == "pass" else "fail" if action == "fail" else "skip"
                update(name, status)
                continue

            if action == "output":
                output = ansi_re.sub("", parsed.get("Output", ""))
                for out_line in output.splitlines():
                    m = go_status_re.match(out_line)
                    if m:
                        status = m.group(1).lower()
                        testname = m.group(2)
                        name = f"{pkg}/{testname}" if pkg else testname
                        update(name, status)
                        continue
                    m = pytest_re.match(out_line.strip())
                    if m:
                        status_map = {
                            "PASSED": "pass",
                            "FAILED": "fail",
                            "ERROR": "fail",
                            "SKIPPED": "skip",
                        }
                        update(m.group("name"), status_map[m.group("status")])
                        continue
                    m = unittest_re.match(out_line.strip())
                    if m:
                        status_map = {
                            "ok": "pass",
                            "fail": "fail",
                            "error": "fail",
                            "skip": "skip",
                            "skipped": "skip",
                        }
                        update(m.group("name"), status_map[m.group("status").lower()])
                continue

            continue

        line_clean = ansi_re.sub("", raw).strip()

        m = go_status_re.match(line_clean)
        if m:
            status = m.group(1).lower()
            testname = m.group(2)
            name = f"{current_pkg}/{testname}" if current_pkg else testname
            update(name, status)
            continue

        m = pytest_re.match(line_clean)
        if m:
            status_map = {
                "PASSED": "pass",
                "FAILED": "fail",
                "ERROR": "fail",
                "SKIPPED": "skip",
            }
            update(m.group("name"), status_map[m.group("status")])
            continue

        m = unittest_re.match(line_clean)
        if m:
            status_map = {
                "ok": "pass",
                "fail": "fail",
                "error": "fail",
                "skip": "skip",
                "skipped": "skip",
            }
            update(m.group("name"), status_map[m.group("status").lower()])
            continue

    return results
